16	import type {MessageChunk} from '../types/ai.js';
17	import type {SessionEntry} from '../types/session.js';
18	import {setLogger} from '../shared/logger.js';
19	
20	// Real upgrades over a real socket: what a list answers is the wire contract, and no double can observe it.
21	
22	interface Frame {
23	  type: string;
24	  sessionId?: string;
25	  resumed?: boolean;
26	  entryCount?: number;
27	  code?: string;
28	  message?: string;
29	  index?: number;
30	  entry?: SessionEntry;
31	  conversations?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
32	}
33	
34	const lines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];
35	const listen = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) => {
36	  lines.push({level, category, message, fields});
37	};
38	
39	beforeEach(() => {
40	  lines.length = 0;
41	  setLogger({debug: listen('debug'), info: listen('info'), warn: listen('warn'), error: listen('error')});
42	});
43	
44	afterEach(async () => {
45	  // Each server sees its sockets close before it stops, so no close lands after the logger below is restored.
46	  await stopEngines();
47	  setLogger();
48	});
49	
50	// An ask sent once the handshake answers, settled by the first frame of the type the ask waits for, which the answer must reach the socket to deliver.
51	const askAfterConnect = async (
52	  url: string,
53	  outbound?: object,
54	  until = 'pong'
55	): Promise<{connected: Frame; frames: Frame[]}> => {
56	  const client = connectClient(url);
57	  const frames: Frame[] = [];
58	  let connected: Frame = {type: ''};
59	  const ask = (frame: Frame): void => {
60	    connected = frame;
61	    if (outbound !== undefined) client.send(JSON.stringify(outbound));
62	  };
63	  await new Promise<void>(resolve => {
64	    client.on('message', raw => {
65	      const frame = JSON.parse(String(raw)) as Frame;
66	      if (frame.type === 'connected') return ask(frame);
67	      frames.push(frame);
68	      if (frame.type === until) return resolve();
69	    });
70	  });
71	  return {connected, frames};
72	};
73	
74	const codesOf = (frames: Frame[]): Array<{type: string; code?: string}> => frames.map(({type, code}) => ({type, code}));
75	
76	const upserts = (frames: Frame[]): Array<{index?: number; entry?: SessionEntry}> =>
77	  frames.filter(frame => frame.type === 'entry_upsert').map(({index, entry}) => ({index, entry}));
78	
79	/** A store whose listFor counts its asks and answers none, so a test can tell whether the store was consulted. */
80	const countingStore = (): {store: SessionStore; asks: () => number} => {
81	  let asks = 0;
82	  return {
83	    store: {
84	      ...delegatingTo(new InMemorySessionStore()),
85	      listFor: () => {
86	        asks += 1;
87	        return [];
88	      },
89	    },
90	    asks: () => asks,
91	  };
92	};
