94	describe('a conversation list over the WebSocket protocol', () => {
95	  it('answers the connected user with ISO summaries, forwarding limit and before while ignoring any client userId', async () => {
96	    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
97	    const newestFirst: SessionSummary[] = [
98	      {
