114	        entryCount: 2,
115	      },
116	    ];
117	    const store: SessionStore = {
118	      ...delegatingTo(new InMemorySessionStore()),
119	      listFor: (userId, options) => {
120	        seen.push({userId, options});
121	        return newestFirst;
122	      },
123	    };
124	
125	    const {frames} = await askAfterConnect(
126	      (await startEngineWith({sessionStore: store, history: {enabled: true}})).url,
