  session: ChatSession,
  orchestrator: ChatOrchestrator,
  options: MessageHandlerOptions,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  const message = validation.valid ? validation.data : undefined;
  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
  answerFrame(ws, session, options, validation);
}

async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  options: MessageHandlerOptions,
  validation: ValidationResult
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_conversations') await answerListConversations(ws, session, options, message);
}

// The list is always the connection's own: the user id comes from the upgrade, and the frame's own user field never reaches the store.
async function answerListConversations(
  ws: WebSocket,
  session: ChatSession,
  options: MessageHandlerOptions,
  message: ListConversationsMessage
): Promise<void> {
  if (!options.history?.enabled || !options.sessionStore) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not enabled on this server');
    return;
  }
  const store = options.sessionStore;
  if (!store.listFor) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'The session store cannot list conversations');
    return;
  }
  try {
    // Both keys, even when undefined, so every store sees one call shape.
    const summaries = await store.listFor(ws.userId, {limit: message.limit, before: message.before});
    sendJson(ws, {type: 'conversation_list', conversations: summaries.map(summaryOnWire)});
  } catch (error) {
    // A store that refuses to list is a misconfiguration, not a failure: an empty history would read as data.
    if (error instanceof StoreCannotList) {
      sendError(ws, ErrorCodes.UNSUPPORTED, 'The session store cannot list conversations');
      return;
    }
    log.error('ws', 'conversation list failed', {
      sessionId: session.sessionId,
      error: error instanceof Error ? error.message : String(error),
    });
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
  }
}

// A summary's dates are `Date`s in the store and ISO strings on the wire, which a `Date` does not survive `JSON.stringify` as.
function summaryOnWire(summary: SessionSummary): ConversationSummary {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  };
}

// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
function isUserMessageFrame(rawMessage: unknown): boolean {
  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
}
