      await h.send();

      const [, hidden] = h.session.entries;
      expect({hidden, toClient: h.frames().filter(frame => /^\w+ 1( |$)/.test(frame))}).toMatchObject({
        hidden: {content: 'Half <thi', truncated: true, isStreaming: false},
